try {
  const text = query || '';
  const parseNum = (matchResult) => {
    if (!matchResult) return null;
    let val = parseFloat(matchResult[1]);
    const unit = (matchResult[2] || '').toLowerCase();
    if (unit.startsWith('k')) val *= 1000;
    else if (unit.startsWith('l')) val *= 100000;
    else if (unit.startsWith('m')) val *= 1000000;
    return val;
  };

  let income = parseNum(text.match(/(?:income|earn|salary|inflow)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
  let expenses = parseNum(text.match(/(?:expense|spend|outgo|cost|bill)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));

  if (income === null || expenses === null) {
    const numbers = [];
    const numRegex = /(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/gi;
    let m;
    while ((m = numRegex.exec(text)) !== null) {
      let val = parseFloat(m[1]);
      const unit = (m[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      numbers.push(val);
    }
    if (numbers.length >= 2) {
      if (income === null && expenses === null) {
        income = Math.max(numbers[0], numbers[1]);
        expenses = Math.min(numbers[0], numbers[1]);
      } else if (income === null) {
        income = numbers.find(n => n !== expenses) || expenses * 1.5;
      } else if (expenses === null) {
        expenses = numbers.find(n => n !== income) || income * 0.6;
      }
    }
  }

  if (income === null || expenses === null) {
    const missing = [];
    if (income === null) missing.push('monthly_income');
    if (expenses === null) missing.push('monthly_expenses');
    return `Error: Missing required inputs for Budget calculation. Required: ${missing.join(', ')}.`;
  }

  if (income <= 0) return 'Error: Income must be greater than zero.';

  const surplus = income - expenses;
  const savings_rate = (surplus / income) * 100;
  const needs_50 = income * 0.50;
  const wants_30 = income * 0.30;
  const savings_20 = income * 0.20;
  const emergency_fund = expenses * 6;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Monthly Income: INR ${fmt(income)}
Monthly Expenses: INR ${fmt(expenses)}
Monthly Surplus: INR ${fmt(surplus)}
Savings Rate: ${savings_rate.toFixed(2)}%
50-30-20 Allocation Plan:
- Needs (50%): INR ${fmt(needs_50)}
- Wants (30%): INR ${fmt(wants_30)}
- Savings (20%): INR ${fmt(savings_20)}
6-Month Emergency Fund Target: INR ${fmt(emergency_fund)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

try {
  const text = query || '';
  const parseNum = (matchResult) => {
    if (!matchResult) return null;
    let val = parseFloat(matchResult[1]);
    const unit = (matchResult[2] || '').toLowerCase();
    if (unit.startsWith('k')) val *= 1000;
    else if (unit.startsWith('l')) val *= 100000;
    else if (unit.startsWith('m')) val *= 1000000;
    return val;
  };

  let sip = parseNum(text.match(/(?:sip|monthly|invest|saving)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
  let rate_annual = null;
  const pctMatch = text.match(/(\d+(?:\.\d+)?)\s*%/);
  if (pctMatch) {
    rate_annual = parseFloat(pctMatch[1]);
  } else {
    const rateMatch = text.match(/(?:rate|return|interest|yield)\D*(\d+(?:\.\d+)?)/i);
    if (rateMatch) rate_annual = parseFloat(rateMatch[1]);
  }

  let years = null;
  const yrMatch = text.match(/(\d+)\s*(?:year|yr|y)/i);
  if (yrMatch) {
    years = parseInt(yrMatch[1]);
  } else {
    const yearsMatch = text.match(/(?:year|duration|time|period)\D*(\d+)/i);
    if (yearsMatch) years = parseInt(yearsMatch[1]);
  }

  if (sip === null || rate_annual === null || years === null) {
    const missing = [];
    if (sip === null) missing.push('monthly_investment');
    if (rate_annual === null) missing.push('expected_return_rate');
    if (years === null) missing.push('years');
    return `Error: Missing required inputs for SIP calculation. Required: ${missing.join(', ')}.`;
  }

  const rate_monthly = rate_annual / 12 / 100;
  const months = years * 12;
  const total_invested = sip * months;
  const maturity_value = sip * ((Math.pow(1 + rate_monthly, months) - 1) / rate_monthly) * (1 + rate_monthly);
  const estimated_returns = maturity_value - total_invested;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Monthly SIP: INR ${fmt(sip)}
Tenure: ${years} years (${months} months)
Expected Return Rate: ${rate_annual.toFixed(2)}%
Total Invested: INR ${fmt(total_invested)}
Maturity Value: INR ${fmt(maturity_value)}
Wealth Gained: INR ${fmt(estimated_returns)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

