  let rate_annual = null;
  const pctMatch = text.match(/(\d+(?:\.\d+)?)\s*%/);
  if (pctMatch) {
    rate_annual = parseFloat(pctMatch[1]);
  } else {
    const rateMatch = text.match(/(?:rate|interest)\D*(\d+(?:\.\d+)?)/i);
    if (rateMatch) rate_annual = parseFloat(rateMatch[1]);
  }

  let years = null;
  const yrMatch = text.match(/(\d+)\s*(?:year|yr|y)/i);
  if (yrMatch) {
    years = parseInt(yrMatch[1]);
  } else {
    const yearsMatch = text.match(/(?:year|duration|time|period|tenure)\D*(\d+)/i);
    if (yearsMatch) years = parseInt(yearsMatch[1]);
  }

  if (principal === null || rate_annual === null || years === null) {
    const missing = [];
    if (principal === null) missing.push('principal');
    if (rate_annual === null) missing.push('annual_interest_rate');
    if (years === null) missing.push('years');
    return `Error: Missing required inputs for EMI calculation. Required: ${missing.join(', ')}.`;
  }

  const rate_monthly = rate_annual / 12 / 100;
  const months = years * 12;
  const emi = principal * rate_monthly * Math.pow(1 + rate_monthly, months) / (Math.pow(1 + rate_monthly, months) - 1);
  const total_payment = emi * months;
  const total_interest = total_payment - principal;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Loan Principal: INR ${fmt(principal)}
Tenure: ${years} years (${months} months)
Annual Interest Rate: ${rate_annual.toFixed(2)}%
Monthly EMI: INR ${fmt(emi)}
Total Payment: INR ${fmt(total_payment)}
Total Interest Payable: INR ${fmt(total_interest)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

